  const tree = new RangeTree([1, 2, 3, 4, 5, 6, 7]);
  tree.add(0, 3, 8);
  tree.add(3, 7, -5);
  tree.add(0, 7, 4);
  tree.assign(0, 7, 0);
  tree.add(0, 7, -2);
  tree.assign(1, 6, -9);
  tree.add(2, 7, 3);
  checkQueries(tree, [-2, -9, -6, -6, -6, -6, 1]);
});

